import { Injectable } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env['API_KEY'] });
  }

  async convertDocument(base64Data: string, mimeType: string, targetFormat: string): Promise<string> {
    const model = 'gemini-2.5-flash';

    let prompt = `You are a high-precision document conversion engine. 
    Analyze the attached file deeply. Extract ALL text content, maintaining the original structure, headers, lists, and tables as closely as possible.

    Output Format Request: ${targetFormat}.

    If the target is 'Markdown', use standard markdown syntax.
    If the target is 'Clean Text', remove all formatting and just provide clear paragraphs.
    If the target is 'HTML', wrap the content in semantic HTML tags (div, p, h1, ul, etc) but do not include <html> or <body> tags.

    Do not include any conversational filler. Output ONLY the converted content.`;

    try {
      const response = await this.ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: mimeType,
                data: base64Data
              }
            },
            {
              text: prompt
            }
          ]
        }
      });

      return response.text || 'Error: No content generated.';
    } catch (error) {
      console.error('Gemini Conversion Error:', error);
      throw error;
    }
  }
}

import { Injectable, signal } from '@angular/core';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
}

@Injectable({
  providedIn: 'root'
})
export class ParticleService {
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private particles: Particle[] = [];
  private animationFrameId: number = 0;
  private width: number = 0;
  private height: number = 0;
  private mouseX: number = 0;
  private mouseY: number = 0;

  // Configuration
  private readonly particleCount = 80;
  private readonly connectionDistance = 150;
  private readonly mouseDistance = 200;

  init(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.resize();
    this.createParticles();
    this.animate();

    window.addEventListener('resize', () => this.resize());
    window.addEventListener('mousemove', (e) => {
      this.mouseX = e.clientX;
      this.mouseY = e.clientY;
    });
  }

  private resize() {
    if (!this.canvas) return;
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.canvas.width = this.width;
    this.canvas.height = this.height;
  }

  private createParticles() {
    this.particles = [];
    for (let i = 0; i < this.particleCount; i++) {
      this.particles.push({
        x: Math.random() * this.width,
        y: Math.random() * this.height,
        vx: (Math.random() - 0.5) * 1.5,
        vy: (Math.random() - 0.5) * 1.5,
        size: Math.random() * 2 + 1
      });
    }
  }

  private animate() {
    if (!this.ctx || !this.canvas) return;

    this.ctx.clearRect(0, 0, this.width, this.height);

    // Update and draw particles
    this.particles.forEach((p, index) => {
      // Movement
      p.x += p.vx;
      p.y += p.vy;

      // Bounce off edges
      if (p.x < 0 || p.x > this.width) p.vx *= -1;
      if (p.y < 0 || p.y > this.height) p.vy *= -1;

      // Mouse interaction
      const dx = this.mouseX - p.x;
      const dy = this.mouseY - p.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance < this.mouseDistance) {
        const forceDirectionX = dx / distance;
        const forceDirectionY = dy / distance;
        const force = (this.mouseDistance - distance) / this.mouseDistance;
        const directionX = forceDirectionX * force * 0.6;
        const directionY = forceDirectionY * force * 0.6;
        p.x -= directionX;
        p.y -= directionY;
      }

      // Draw particle
      this.ctx!.fillStyle = '#3b82f6'; // Tailwind blue-500
      this.ctx!.beginPath();
      this.ctx!.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      this.ctx!.fill();

      // Connect particles
      for (let j = index + 1; j < this.particles.length; j++) {
        const p2 = this.particles[j];
        const dx2 = p.x - p2.x;
        const dy2 = p.y - p2.y;
        const dist2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);

        if (dist2 < this.connectionDistance) {
          this.ctx!.strokeStyle = `rgba(59, 130, 246, ${1 - dist2 / this.connectionDistance})`;
          this.ctx!.lineWidth = 1;
          this.ctx!.beginPath();
          this.ctx!.moveTo(p.x, p.y);
          this.ctx!.lineTo(p2.x, p2.y);
          this.ctx!.stroke();
        }
      }
    });

    this.animationFrameId = requestAnimationFrame(() => this.animate());
  }

  destroy() {
    cancelAnimationFrame(this.animationFrameId);
    window.removeEventListener('resize', () => this.resize());
  }
}

import { Component, ElementRef, ViewChild, AfterViewInit, OnDestroy, signal, computed, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ParticleService } from './services/particles.service';
import { GeminiService } from './services/gemini.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: []
})
export class AppComponent implements AfterViewInit, OnDestroy {
  @ViewChild('particleCanvas') canvasRef!: ElementRef<HTMLCanvasElement>;

  // Services
  private particleService = inject(ParticleService);
  private geminiService = inject(GeminiService);

  // Signals for state management
  isDragOver = signal(false);
  isProcessing = signal(false);
  progress = signal(0); // Simulated progress

  uploadedFile = signal<{ name: string; type: string; base64: string } | null>(null);
  convertedContent = signal<string>('');

  targetFormat = signal<string>('Markdown');
  formats = ['Markdown', 'Clean Text', 'HTML', 'JSON Structure'];

  // Computed
  hasResult = computed(() => this.convertedContent().length > 0);

  ngAfterViewInit() {
    this.particleService.init(this.canvasRef.nativeElement);
  }

  ngOnDestroy() {
    this.particleService.destroy();
  }

  // Drag and Drop Handlers
  onDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(true);
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(false);
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(false);

    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.handleFile(files[0]);
    }
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      this.handleFile(input.files[0]);
    }
  }

  private handleFile(file: File) {
    if (!file) return;

    // Validate type (basic check, Gemini handles most)
    // We allow PDF, Images, Text
    const reader = new FileReader();
    reader.onload = (e) => {
      const base64Raw = e.target?.result as string;
      // Remove data URL prefix for API
      const base64Data = base64Raw.split(',')[1];

      this.uploadedFile.set({
        name: file.name,
        type: file.type,
        base64: base64Data
      });

      // Reset previous results
      this.convertedContent.set('');
    };
    reader.readAsDataURL(file);
  }

  async startConversion() {
    const file = this.uploadedFile();
    if (!file) return;

    this.isProcessing.set(true);
    this.simulateProgress();

    try {
      const result = await this.geminiService.convertDocument(
        file.base64,
        file.type,
        this.targetFormat()
      );
      this.convertedContent.set(result);
      this.progress.set(100);
    } catch (error) {
      alert('Conversion failed. Please try again.');
      console.error(error);
    } finally {
      this.isProcessing.set(false);
    }
  }

  simulateProgress() {
    this.progress.set(0);
    const interval = setInterval(() => {
      if (!this.isProcessing()) {
        clearInterval(interval);
        return;
      }

      this.progress.update(p => {
        if (p >= 90) return p;
        return p + Math.floor(Math.random() * 5) + 1;
      });
    }, 200);
  }

  downloadResult() {
    const content = this.convertedContent();
    const format = this.targetFormat().toLowerCase().replace(' ', '_');
    const extension = format === 'markdown' ? 'md' : format === 'html' ? 'html' : 'txt';
    const filename = `nebula_converted_${Date.now()}.${extension}`;

    const blob = new Blob([content], { type: 'text/plain' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    window.URL.revokeObjectURL(url);
  }

  reset() {
    this.uploadedFile.set(null);
    this.convertedContent.set('');
    this.progress.set(0);
    this.isProcessing.set(false);
  }
}

{
  "name": "Nebula Converter AI",
  "description": "A high-fidelity document transmutation tool with a golden particle core.",
  "requestFramePermissions": []
}

import { Injectable } from '@angular/core';

interface Point3D {
  x: number;
  y: number;
  z: number;
  size: number;
  baseColor: string;
}

@Injectable({
  providedIn: 'root'
})
export class ParticleService {
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private particles: Point3D[] = [];
  private animationFrameId: number = 0;
  private width: number = 0;
  private height: number = 0;

  // Interaction
  private mouseX: number = 0;
  private mouseY: number = 0;
  private targetRotationX: number = 0;
  private targetRotationY: number = 0;
  private currentRotationX: number = 0;
  private currentRotationY: number = 0;

  // Configuration
  private readonly particleCount = 1200; // Dense sphere
  private readonly sphereRadius = 250;
  private readonly perspective = 800;

  init(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.resize();
    this.createSphereParticles();
    this.animate();

    window.addEventListener('resize', () => this.resize());
    window.addEventListener('mousemove', (e) => {
      const rect = this.canvas?.getBoundingClientRect();
      if(rect) {
        this.mouseX = e.clientX - rect.left - this.width / 2;
        this.mouseY = e.clientY - rect.top - this.height / 2;
      }
    });
  }

  private resize() {
    if (!this.canvas) return;
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.canvas.width = this.width;
    this.canvas.height = this.height;
  }

  private createSphereParticles() {
    this.particles = [];
    for (let i = 0; i < this.particleCount; i++) {
      // Uniform distribution on sphere surface
      // Using Fibonacci sphere algorithm for even distribution
      const phi = Math.acos(1 - 2 * (i + 0.5) / this.particleCount);
      const theta = Math.PI * (1 + Math.sqrt(5)) * i;

      const x = this.sphereRadius * Math.sin(phi) * Math.cos(theta);
      const y = this.sphereRadius * Math.sin(phi) * Math.sin(theta);
      const z = this.sphereRadius * Math.cos(phi);

      // Color variation: Gold, Orange, White
      const rand = Math.random();
      let color;
      if (rand > 0.9) color = '#ffffff'; // Sparkle
      else if (rand > 0.6) color = '#facc15'; // Yellow-400
      else color = '#d97706'; // Amber-600

      this.particles.push({
        x, y, z,
        size: Math.random() * 1.5 + 0.5,
        baseColor: color
      });
    }
  }

  private animate() {
    if (!this.ctx || !this.canvas) return;

    this.ctx.fillStyle = '#000000';
    this.ctx.fillRect(0, 0, this.width, this.height);

    // Rotation logic
    this.targetRotationY = this.mouseX * 0.0001;
    this.targetRotationX = this.mouseY * 0.0001;

    // Smooth ease
    this.currentRotationY += (this.targetRotationY - this.currentRotationY) * 0.05;
    this.currentRotationX += (this.targetRotationX - this.currentRotationX) * 0.05;

    // Auto rotate
    this.currentRotationY += 0.002;

    const cx = this.width / 2;
    const cy = this.height / 2;

    // Global Composite for glow effect
    this.ctx.globalCompositeOperation = 'lighter';

    this.particles.forEach(p => {
      // Rotate around Y
      let x1 = p.x * Math.cos(this.currentRotationY) - p.z * Math.sin(this.currentRotationY);
      let z1 = p.z * Math.cos(this.currentRotationY) + p.x * Math.sin(this.currentRotationY);

      // Rotate around X
      let y1 = p.y * Math.cos(this.currentRotationX) - z1 * Math.sin(this.currentRotationX);
      let z2 = z1 * Math.cos(this.currentRotationX) + p.y * Math.sin(this.currentRotationX);

      // Perspective projection
      const scale = this.perspective / (this.perspective + z2);
      const x2d = cx + x1 * scale;
      const y2d = cy + y1 * scale;

      // Draw only if in front of camera (roughly)
      if (scale > 0) {
        const alpha = Math.max(0, (z2 + this.sphereRadius) / (2 * this.sphereRadius)); // Depth cueing

        this.ctx!.fillStyle = p.baseColor;
        this.ctx!.globalAlpha = alpha;

        this.ctx!.beginPath();
        this.ctx!.arc(x2d, y2d, p.size * scale, 0, Math.PI * 2);
        this.ctx!.fill();
      }
    });

    this.ctx.globalAlpha = 1.0;
    this.ctx.globalCompositeOperation = 'source-over';

    this.animationFrameId = requestAnimationFrame(() => this.animate());
  }

  destroy() {
    cancelAnimationFrame(this.animationFrameId);
    window.removeEventListener('resize', () => this.resize());
  }
}

