import { Injectable } from '@angular/core';

interface Point3D {
  x: number;
  y: number;
  z: number;
  size: number;
  baseColor: string;
  originalX: number;
  originalY: number;
  originalZ: number;
}

@Injectable({
  providedIn: 'root'
})
export class ParticleService {
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private particles: Point3D[] = [];
  private animationFrameId: number = 0;
  private width: number = 0;
  private height: number = 0;

  // Interaction & State
  private mouseX: number = 0;
  private mouseY: number = 0;
  private currentRotationX: number = 0;
  private currentRotationY: number = 0;

  // App State
  private progress: number = 0;

  // Configuration
  private readonly particleCount = 1000;
  private readonly sphereRadius = 220;
  private readonly perspective = 800;

  init(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.resize();
    this.createSphereParticles();
    this.animate();

    window.addEventListener('resize', () => this.resize());
    window.addEventListener('mousemove', (e) => {
      const rect = this.canvas?.getBoundingClientRect();
      if(rect) {
        this.mouseX = (e.clientX - rect.left - this.width / 2);
        this.mouseY = (e.clientY - rect.top - this.height / 2);
      }
    });
  }

  setProgress(p: number) {
    this.progress = p;
  }

  private resize() {
    if (!this.canvas) return;
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.canvas.width = this.width;
    this.canvas.height = this.height;
  }

  private createSphereParticles() {
    this.particles = [];
    for (let i = 0; i < this.particleCount; i++) {
      const phi = Math.acos(1 - 2 * (i + 0.5) / this.particleCount);
      const theta = Math.PI * (1 + Math.sqrt(5)) * i;

      const x = this.sphereRadius * Math.sin(phi) * Math.cos(theta);
      const y = this.sphereRadius * Math.sin(phi) * Math.sin(theta);
      const z = this.sphereRadius * Math.cos(phi);

      const rand = Math.random();
      let color;
      if (rand > 0.90) color = '#ffffff'; // Core highlights
      else if (rand > 0.6) color = '#fbbf24'; // Amber-400
      else color = '#d97706'; // Amber-600

      this.particles.push({
        x, y, z,
        originalX: x, originalY: y, originalZ: z,
        size: Math.random() * 2 + 0.5,
        baseColor: color
      });
    }
  }

  private animate() {
    if (!this.ctx || !this.canvas) return;

    // Clear with slight fade for trail effect if desired, but sticking to clean clear for sharp holographic look
    this.ctx.fillStyle = '#000000';
    this.ctx.fillRect(0, 0, this.width, this.height);

    // Calculate rotation speeds based on state
    const isProcessing = this.progress > 0 && this.progress < 100;

    // Base rotation from mouse (interactive)
    const targetRotY = this.mouseX * 0.0001;
    const targetRotX = this.mouseY * 0.0001;

    // Auto rotation speed
    // When processing, it spins much faster
    const autoSpeed = isProcessing ? 0.05 + (this.progress / 2000) : 0.003;

    this.currentRotationY += (targetRotY - this.currentRotationY) * 0.05 + autoSpeed;
    this.currentRotationX += (targetRotX - this.currentRotationX) * 0.05;

    const cx = this.width / 2;
    const cy = this.height / 2;

    this.ctx.globalCompositeOperation = 'lighter';

    // Pulse factor for "working" state
    const pulse = isProcessing ? 1 + Math.sin(Date.now() * 0.01) * 0.05 : 1;
    // Expansion factor based on progress
    const expansion = isProcessing ? 1 + (this.progress / 500) : 1; // Expands up to 20%

    const scaleFactor = pulse * expansion;

    this.particles.forEach(p => {
      // Apply transforms
      // 1. Scale/Pulse
      let x = p.originalX * scaleFactor;
      let y = p.originalY * scaleFactor;
      let z = p.originalZ * scaleFactor;

      // 2. Jitter when processing (simulating data crunching)
      if (isProcessing) {
        const jitterAmount = (this.progress / 100) * 5;
        x += (Math.random() - 0.5) * jitterAmount;
        y += (Math.random() - 0.5) * jitterAmount;
        z += (Math.random() - 0.5) * jitterAmount;
      }

      // 3. Rotation Y
      let x1 = x * Math.cos(this.currentRotationY) - z * Math.sin(this.currentRotationY);
      let z1 = z * Math.cos(this.currentRotationY) + x * Math.sin(this.currentRotationY);

      // 4. Rotation X
      let y1 = y * Math.cos(this.currentRotationX) - z1 * Math.sin(this.currentRotationX);
      let z2 = z1 * Math.cos(this.currentRotationX) + y * Math.sin(this.currentRotationX);

      // 5. Projection
      const scale = this.perspective / (this.perspective + z2);
      const x2d = cx + x1 * scale;
      const y2d = cy + y1 * scale;

      if (scale > 0) {
        // Depth alpha
        const alpha = Math.max(0.1, (z2 + this.sphereRadius * 2) / (3 * this.sphereRadius));

        this.ctx!.fillStyle = p.baseColor;
        this.ctx!.globalAlpha = alpha;

        // Draw particle
        this.ctx!.beginPath();
        this.ctx!.arc(x2d, y2d, p.size * scale, 0, Math.PI * 2);
        this.ctx!.fill();

        // Connect lines randomly for "network" feel if close and processing
        // Optimization: Only check a few neighbors or random chance to avoid O(N^2)
        if (isProcessing && Math.random() > 0.98) {
           this.ctx!.strokeStyle = 'rgba(251, 191, 36, 0.1)'; // Amber line
           this.ctx!.beginPath();
           this.ctx!.moveTo(cx, cy); // Beam from center
           this.ctx!.lineTo(x2d, y2d);
           this.ctx!.stroke();
        }
      }
    });

    // Draw a "Core" ring when processing
    if (isProcessing) {
        this.ctx.strokeStyle = `rgba(251, 191, 36, ${this.progress/200})`;
        this.ctx.lineWidth = 2;
        this.ctx.beginPath();
        this.ctx.arc(cx, cy, this.sphereRadius * scaleFactor * 1.1, 0, Math.PI * 2);
        this.ctx.stroke();
    }

    this.ctx.globalAlpha = 1.0;
    this.ctx.globalCompositeOperation = 'source-over';

    this.animationFrameId = requestAnimationFrame(() => this.animate());
  }

  destroy() {
    cancelAnimationFrame(this.animationFrameId);
    window.removeEventListener('resize', () => this.resize());
  }
}

import { Component, ElementRef, ViewChild, AfterViewInit, OnDestroy, signal, computed, inject, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ParticleService } from './services/particles.service';
import { GeminiService } from './services/gemini.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: []
})
export class AppComponent implements AfterViewInit, OnDestroy {
  @ViewChild('particleCanvas') canvasRef!: ElementRef<HTMLCanvasElement>;

  // Services
  private particleService = inject(ParticleService);
  private geminiService = inject(GeminiService);

  // Signals
  isDragOver = signal(false);
  isProcessing = signal(false);
  progress = signal(0);

  uploadedFile = signal<{ name: string; type: string; base64: string } | null>(null);
  convertedContent = signal<string>('');

  targetFormat = signal<string>('Markdown');
  formats = ['Markdown', 'Plain Text', 'HTML', 'JSON'];

  // Computed
  hasResult = computed(() => this.convertedContent().length > 0);

  constructor() {
    // Reactively update particle system when progress changes
    effect(() => {
      this.particleService.setProgress(this.progress());
    });
  }

  ngAfterViewInit() {
    this.particleService.init(this.canvasRef.nativeElement);
  }

  ngOnDestroy() {
    this.particleService.destroy();
  }

  // Drag and Drop
  onDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(true);
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(false);
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragOver.set(false);

    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.handleFile(files[0]);
    }
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      this.handleFile(input.files[0]);
    }
  }

  private handleFile(file: File) {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64Raw = e.target?.result as string;
      const base64Data = base64Raw.split(',')[1];

      this.uploadedFile.set({
        name: file.name,
        type: file.type,
        base64: base64Data
      });

      this.convertedContent.set('');
      this.progress.set(0);
    };
    reader.readAsDataURL(file);
  }

  async startConversion() {
    const file = this.uploadedFile();
    if (!file) return;

    this.isProcessing.set(true);
    this.simulateProgress();

    try {
      const result = await this.geminiService.convertDocument(
        file.base64,
        file.type,
        this.targetFormat()
      );
      this.convertedContent.set(result);
      this.progress.set(100);
    } catch (error) {
      alert('Conversion failed. Please check your API key and file.');
      console.error(error);
      this.progress.set(0);
    } finally {
      this.isProcessing.set(false);
    }
  }

  simulateProgress() {
    this.progress.set(1);
    const interval = setInterval(() => {
      if (!this.isProcessing()) {
        clearInterval(interval);
        if (this.hasResult()) this.progress.set(100);
        else this.progress.set(0);
        return;
      }

      this.progress.update(p => {
        // Slow down as we approach 90%
        if (p >= 90) return p;
        const inc = Math.max(1, Math.floor(Math.random() * 3));
        return p + inc;
      });
    }, 100);
  }

  downloadResult() {
    const content = this.convertedContent();
    const format = this.targetFormat().toLowerCase().replace(' ', '_');

    let extension = 'txt';
    if (format.includes('markdown')) extension = 'md';
    if (format.includes('html')) extension = 'html';
    if (format.includes('json')) extension = 'json';

    const filename = `nebula_output_${Date.now()}.${extension}`;

    const blob = new Blob([content], { type: 'text/plain' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    window.URL.revokeObjectURL(url);
  }

  reset() {
    this.uploadedFile.set(null);
    this.convertedContent.set('');
    this.progress.set(0);
    this.isProcessing.set(false);
  }
}

import { Injectable } from '@angular/core';
import { GoogleGenAI } from '@google/genai';
import JSZip from 'jszip';

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env['API_KEY'] });
  }

  async convertDocument(base64Data: string, mimeType: string, targetFormat: string): Promise<string> {
    const model = 'gemini-2.5-flash';

    const basePrompt = `You are a high-precision document conversion engine. 
    Analyze the provided content deeply. Extract ALL text content, maintaining the original structure, headers, lists, and tables as closely as possible.

    Output Format Request: ${targetFormat}.

    If the target is 'Markdown', use standard markdown syntax.
    If the target is 'Clean Text', remove all formatting and just provide clear paragraphs.
    If the target is 'HTML', wrap the content in semantic HTML tags (div, p, h1, ul, etc) but do not include <html> or <body> tags.

    Do not include any conversational filler. Output ONLY the converted content.`;

    try {
      let parts: any[] = [];

      // Handle EPUB specifically because Gemini doesn't support 'application/epub+zip' natively
      if (mimeType === 'application/epub+zip') {
        const extractedText = await this.extractEpubContent(base64Data);
        parts = [
          { text: basePrompt },
          { text: "Here is the extracted raw content from the EPUB file:\n\n" + extractedText }
        ];
      } else {
        // For supported formats (PDF, Image, Text, etc.)
        parts = [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: basePrompt
          }
        ];
      }

      const response = await this.ai.models.generateContent({
        model: model,
        contents: {
          parts: parts
        }
      });

      return response.text || 'Error: No content generated.';
    } catch (error) {
      console.error('Gemini Conversion Error:', error);
      throw error;
    }
  }

  private async extractEpubContent(base64Data: string): Promise<string> {
    try {
      const zip = new JSZip();

      // Convert base64 to Uint8Array
      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      // Load zip
      const loadedZip = await zip.loadAsync(bytes);
      const filePromises: Promise<string>[] = [];

      // Iterate through files to find HTML/XHTML content
      loadedZip.forEach((relativePath, file) => {
        const lowerPath = relativePath.toLowerCase();
        if (!file.dir && (lowerPath.endsWith('.xhtml') || lowerPath.endsWith('.html') || lowerPath.endsWith('.htm'))) {
          // Extract text content from the file
          filePromises.push(
            file.async('string').then(content => `\n<!-- FILE START: ${relativePath} -->\n${content}\n<!-- FILE END -->\n`)
          );
        }
      });

      if (filePromises.length === 0) {
        return "Error: No text content found in EPUB container.";
      }

      const contents = await Promise.all(filePromises);
      return contents.join('');
    } catch (err) {
      console.error('EPUB Parsing Error', err);
      return "Error parsing EPUB file structure. Please ensure it is a valid EPUB.";
    }
  }
}

