import { Injectable } from '@angular/core';
import JSZip from 'jszip';
import * as pdfjsLib from 'pdfjs-dist';
import TurndownService from 'turndown';

// Configure the worker for PDF.js to load from the ESM CDN
(pdfjsLib as any).GlobalWorkerOptions.workerSrc = 'https://esm.sh/pdfjs-dist@3.11.174/build/pdf.worker.min.js';

@Injectable({ providedIn: 'root' })
export class LocalConverterService {

  async convert(fileData: { base64: string, type: string, name: string }, targetFormat: string): Promise<string> {
    // Convert base64 back to ArrayBuffer for local processing
    const binaryString = atob(fileData.base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    const arrayBuffer = bytes.buffer;

    let content = '';

    try {
      if (fileData.type === 'application/pdf') {
        content = await this.processPDF(arrayBuffer);
      } else if (fileData.type.includes('epub') || fileData.name.toLowerCase().endsWith('.epub')) {
        content = await this.processEPUB(arrayBuffer, targetFormat);
      } else if (fileData.type.includes('text') || fileData.name.toLowerCase().endsWith('.txt') || fileData.name.toLowerCase().endsWith('.md')) {
        content = new TextDecoder('utf-8').decode(bytes);
      } else {
        return `SYSTEM WARNING: Format [${fileData.type}] is not supported in pure local mode.\nSupported formats: PDF, EPUB, TXT, MD.`;
      }

      return this.formatOutput(content, targetFormat);

    } catch (err: any) {
      console.error('Local Conversion Error:', err);
      return `PROCESSING ERROR: ${err.message || 'Unknown error occurred during local conversion.'}`;
    }
  }

  private async processPDF(data: ArrayBuffer): Promise<string> {
    const loadingTask = pdfjsLib.getDocument({ data });
    const pdf = await loadingTask.promise;
    let fullText = '';

    // Iterate through all pages
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      // Simple text extraction - structure is loosely preserved by line breaks
      const pageText = textContent.items
        .map((item: any) => item.str)
        .join(' ');

      fullText += `\n\n--- Page ${i} ---\n\n${pageText}`;
    }
    return fullText;
  }

  private async processEPUB(data: ArrayBuffer, targetFormat: string): Promise<string> {
    const zip = new JSZip();
    const loadedZip = await zip.loadAsync(data);
    const turndownService = new TurndownService();

    let combinedText = '';

    // Find all HTML-like files
    const htmlFiles: {name: string, content: string}[] = [];

    await Promise.all(
      Object.keys(loadedZip.files).map(async (filename) => {
         // Filter for xhtml/html and avoid system files
         if (filename.match(/\.(xhtml|html|htm)$/i) && !filename.startsWith('__') && !filename.includes('nav')) {
            const str = await loadedZip.files[filename].async('string');
            htmlFiles.push({ name: filename, content: str });
         }
      })
    );

    // Sort filenames to try and maintain reading order (heuristic)
    htmlFiles.sort((a, b) => a.name.localeCompare(b.name));

    const parser = new DOMParser();

    for (const file of htmlFiles) {
      const doc = parser.parseFromString(file.content, 'text/html');

      // Clean up common EPUB artifacts if needed
      if (targetFormat === 'Markdown') {
         // Convert HTML to Markdown
         const md = turndownService.turndown(doc.body.innerHTML);
         combinedText += `\n\n` + md;
      } else if (targetFormat === 'HTML') {
         combinedText += `\n\n<!-- Section: ${file.name} -->\n` + doc.body.innerHTML;
      } else {
         // Plain text
         combinedText += `\n\n` + (doc.body.textContent || '');
      }
    }

    return combinedText || "Error: No text content extracted from EPUB.";
  }

  private formatOutput(text: string, format: string): string {
    if (format === 'JSON') {
      return JSON.stringify({ 
        generatedAt: new Date().toISOString(),
        content: text 
      }, null, 2);
    }

    if (format === 'HTML') {
      // If content is already HTML (from EPUB), wrap it. If plain text, simple wrap.
      if (text.includes('<p>') || text.includes('<div>')) {
        return `<div class="converted-content">\n${text}\n</div>`;
      }
      return `<div class="converted-content">\n${text.split('\n').map(l => l.trim() ? `<p>${l}</p>` : '').join('')}\n</div>`;
    }

    // Default: Plain Text / Markdown
    // (EPUB conversion already handled MD specific logic in extract)
    return text;
  }
}

