import { Injectable } from '@angular/core';
import * as THREE from 'three';

@Injectable({
  providedIn: 'root'
})
export class ParticleService {
  private canvas: HTMLCanvasElement | null = null;
  private renderer: THREE.WebGLRenderer | null = null;
  private scene: THREE.Scene | null = null;
  private camera: THREE.PerspectiveCamera | null = null;

  private particlesMesh: THREE.Points | null = null;
  private animationFrameId: number = 0;

  // State
  private progress: number = 0;
  private mouseX: number = 0;
  private mouseY: number = 0;

  // Settings
  private readonly particleCount = 1800;
  private readonly baseColor = 0xf59e0b; // Amber 500

  init(canvas: HTMLCanvasElement) {
    this.canvas = canvas;

    // 1. Setup Renderer
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      alpha: true, // Transparent background
      antialias: true
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    // 2. Setup Scene & Camera
    this.scene = new THREE.Scene();
    // No background color set so it remains transparent (CSS handles bg)
    // this.scene.fog = new THREE.FogExp2(0x000000, 0.002); 

    this.camera = new THREE.PerspectiveCamera(
      75, 
      window.innerWidth / window.innerHeight, 
      0.1, 
      1000
    );
    this.camera.position.z = 400;

    // 3. Create Particles
    this.createParticleSystem();

    // 4. Listeners
    window.addEventListener('resize', this.onResize.bind(this));
    window.addEventListener('mousemove', this.onMouseMove.bind(this));

    // 5. Start Loop
    this.animate();
  }

  setProgress(p: number) {
    this.progress = p;
  }

  private createParticleSystem() {
    if (!this.scene) return;

    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(this.particleCount * 3);
    const sizes = new Float32Array(this.particleCount);

    const radius = 180;

    for (let i = 0; i < this.particleCount; i++) {
      // Create a spherical distribution
      const theta = THREE.MathUtils.randFloatSpread(360); 
      const phi = THREE.MathUtils.randFloatSpread(360); 

      // Use spherical coordinates for uniform sphere, or just random xyz for a cloud
      // Let's do a "cloud" inside a sphere volume
      const r = radius * Math.cbrt(Math.random()); // Uniform distribution inside sphere
      const x = r * Math.sin(theta) * Math.cos(phi);
      const y = r * Math.sin(theta) * Math.sin(phi);
      const z = r * Math.cos(theta);

      positions[i * 3] = x;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = z;

      sizes[i] = Math.random() * 2;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

    // Create a custom shader material or standard PointsMaterial
    const material = new THREE.PointsMaterial({
      color: this.baseColor,
      size: 2,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending
    });

    this.particlesMesh = new THREE.Points(geometry, material);
    this.scene.add(this.particlesMesh);
  }

  private onResize() {
    if (!this.camera || !this.renderer) return;
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }

  private onMouseMove(event: MouseEvent) {
    // Normalize mouse position from -1 to 1
    this.mouseX = (event.clientX / window.innerWidth) * 2 - 1;
    this.mouseY = -(event.clientY / window.innerHeight) * 2 + 1;
  }

  private animate() {
    this.animationFrameId = requestAnimationFrame(this.animate.bind(this));

    if (!this.scene || !this.camera || !this.renderer || !this.particlesMesh) return;

    const time = Date.now() * 0.0005;
    const isProcessing = this.progress > 0 && this.progress < 100;

    // --- Animation Logic ---

    // 1. Rotation
    // Base rotation + Mouse influence
    const targetRotX = this.mouseY * 0.5;
    const targetRotY = this.mouseX * 0.5;

    // Processing speed boost
    const processingSpeed = isProcessing ? 0.02 + (this.progress / 1000) : 0.001;

    this.particlesMesh.rotation.y += processingSpeed;
    this.particlesMesh.rotation.x += (targetRotX * 0.05 - this.particlesMesh.rotation.x) * 0.1;
    this.particlesMesh.rotation.z += (targetRotY * 0.05 - this.particlesMesh.rotation.z) * 0.1;

    // 2. Pulse / Scale based on progress
    if (isProcessing) {
        // Heartbeat effect
        const pulse = 1 + Math.sin(Date.now() * 0.01) * 0.1;
        // Expansion based on progress percentage
        const expansion = 1 + (this.progress / 200); 
        const scale = pulse * expansion;

        this.particlesMesh.scale.setScalar(scale);

        // Color Shift (Brighter when processing)
        (this.particlesMesh.material as THREE.PointsMaterial).color.setHex(0xffffff);
        (this.particlesMesh.material as THREE.PointsMaterial).opacity = 0.5 + Math.random() * 0.5;
    } else {
        // Return to normal
        const currentScale = this.particlesMesh.scale.x;
        const targetScale = 1 + Math.sin(time) * 0.05; // Gentle breathe

        this.particlesMesh.scale.setScalar(
            currentScale + (targetScale - currentScale) * 0.05
        );

        (this.particlesMesh.material as THREE.PointsMaterial).color.setHex(this.baseColor);
        (this.particlesMesh.material as THREE.PointsMaterial).opacity = 0.8;
    }

    // 3. Camera subtle float
    this.camera.position.x += (this.mouseX * 20 - this.camera.position.x) * 0.05;
    this.camera.position.y += (this.mouseY * 20 - this.camera.position.y) * 0.05;
    this.camera.lookAt(this.scene.position);

    this.renderer.render(this.scene, this.camera);
  }

  destroy() {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
    window.removeEventListener('resize', this.onResize);
    window.removeEventListener('mousemove', this.onMouseMove);

    if (this.renderer) {
      this.renderer.dispose();
    }
  }
}

import { Injectable } from '@angular/core';
import * as THREE from 'three';

@Injectable({
